function verifier(string $nom): void
{
    $messages = [
        "447b6f819f53a473076fe495f5fb34b174075de563c6d64b5eefa2fdda3a9755" => "Ce n'est pas lui ! Axel a bien badgé à la Salle des fêtes ce soir-là, mais lisez son témoignage : il a un alibi, et il a vu le vrai coupable.",
        "939d4ced0a2dff31528550edc58b53c73bd39dc76b78fd2093c799ced96e0284" => "Bravo, vous avez démasqué la coupable sans tomber dans le piège ! L'ancienne Reine du carnaval n'avait pas digéré de rendre sa couronne. Le char sera repeint à temps pour le défilé.",
    ];
    $empreinte = hash('sha256', strtolower(trim($nom)));
    echo "\n[[ENQUETE:" . (isset($messages[$empreinte]) ? $empreinte : "KO") . "]]\n";
    if (isset($messages[$empreinte])) {
        echo $messages[$empreinte] . "\n";
    } else {
        echo "Ce n'est pas la bonne personne. Essayez encore !\n";
    }
}

